/* Progressive enhancement: reuse original nodes, listeners and API contracts. */
'use strict';
(()=>{
const main=document.querySelector('main');if(main){main.id ||= 'maha-main';const skip=document.createElement('a');skip.href='#'+main.id;skip.className='ui-skip';skip.textContent='Skip to content';document.body.prepend(skip);main.tabIndex=-1;}
let sequence=0;
window.MAHA_CONFIRM=message=>new Promise(resolve=>{const previous=document.activeElement;const dialog=document.createElement('dialog');const heading=document.createElement('h2');heading.id='ui-confirm-title';heading.textContent='Confirm change';dialog.setAttribute('aria-labelledby',heading.id);const copy=document.createElement('p');copy.textContent=message;const cancel=document.createElement('button');cancel.className='ui-trigger';cancel.textContent='Cancel';const confirm=document.createElement('button');confirm.className='action';confirm.textContent='Confirm';let accepted=false;cancel.onclick=()=>dialog.close();confirm.onclick=()=>{accepted=true;dialog.close();};dialog.append(heading,copy,cancel,document.createTextNode(' '),confirm);document.body.append(dialog);dialog.addEventListener('close',()=>{dialog.remove();previous?.focus();resolve(accepted);},{once:true});dialog.showModal();cancel.focus();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const details=document.activeElement?.closest('details[open]');if(details){event.preventDefault();event.stopPropagation();details.open=false;details.querySelector('summary')?.focus();}}},true);
document.addEventListener('click',event=>{document.querySelectorAll('details.tag-picker[open]').forEach(details=>{if(!details.contains(event.target))details.open=false;});});

function positionFilter(dialog,trigger){if(!dialog.open)return;const a=trigger.getBoundingClientRect(),pad=12,gap=8;const below=innerHeight-a.bottom-gap-pad,above=a.top-gap-pad;const useAbove=below<Math.min(320,dialog.scrollHeight)&&above>below;const available=Math.max(120,useAbove?above:below);dialog.style.maxHeight=Math.min(innerHeight-2*pad,available)+'px';const r=dialog.getBoundingClientRect();dialog.style.left=Math.max(pad,Math.min(a.left,innerWidth-r.width-pad))+'px';dialog.style.top=Math.max(pad,Math.min(useAbove?a.top-gap-r.height:a.bottom+gap,innerHeight-r.height-pad))+'px';dialog._filterTrigger=trigger;}
function repositionFilters(){document.querySelectorAll('dialog.ui-filter-panel[open]').forEach(d=>{if(d._filterTrigger)positionFilter(d,d._filterTrigger);});}addEventListener('resize',repositionFilters);document.addEventListener('scroll',event=>{if(!event.target.closest?.('.ui-filter-panel'))repositionFilters();},true);
function panel(title,trigger,kind=''){const dialog=document.createElement('dialog');dialog.className='ui-drawer '+kind;dialog.id='ui-panel-'+(++sequence);dialog.setAttribute('aria-labelledby',dialog.id+'-title');const head=document.createElement('div');head.className='ui-panel-head';const heading=document.createElement('h2');heading.id=dialog.id+'-title';heading.textContent=title;const close=document.createElement('button');close.type='button';close.className='ui-trigger';close.textContent='Close';head.append(heading,close);if(kind==='ui-filter-panel')dialog.append(heading,close);else dialog.append(head);document.body.append(dialog);trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls',dialog.id);trigger.setAttribute('aria-expanded','false');trigger.addEventListener('click',()=>{if(!dialog.open){dialog.showModal();if(kind==='ui-filter-panel')positionFilter(dialog,trigger);trigger.setAttribute('aria-expanded','true');}});close.onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{trigger.setAttribute('aria-expanded','false');trigger.focus();});return dialog;}
const nav=document.querySelector('body>header>nav');if(nav){const trigger=document.createElement('button');trigger.type='button';trigger.className='ui-trigger ui-menu-trigger';trigger.textContent='Menu';nav.after(trigger);const drawer=panel('Explore MAHA',trigger,'ui-navigation');nav.closest('header').append(drawer);const marker=document.createComment('navigation');nav.before(marker);const query=matchMedia('(max-width:1000px)');function adapt(){if(query.matches)drawer.append(nav);else{if(drawer.open)drawer.close();marker.after(nav);}}query.addEventListener('change',adapt);adapt();nav.addEventListener('click',e=>{if(e.target.closest('a')&&drawer.open)drawer.close();});}
function enhanceFilters(){document.querySelectorAll('.catalog-controls,.music-filters').forEach(controls=>{if(controls.closest('dialog')||controls.dataset.uiEnhanced)return;controls.dataset.uiEnhanced='true';const trigger=document.createElement('button');trigger.type='button';trigger.className='ui-trigger ui-filter-trigger';trigger.textContent='Sort & filters';controls.before(trigger);const drawer=panel('Sort & filters',trigger,'ui-filter-panel');const note=document.createElement('p');note.className='ui-panel-note';note.textContent='Changes apply immediately. Close this panel to explore your results.';drawer.append(note,controls);const update=()=>{const n=[...controls.querySelectorAll('select')].filter(s=>!s.hidden&&s.selectedIndex>0).length;trigger.textContent='Sort & filters'+(n?' · '+n+' changed':'');};controls.addEventListener('change',update);update();});}
document.querySelectorAll('#books,#archives,#songs').forEach(target=>{if(target.children.length)return;const loading=document.createElement('div');loading.className='ui-loading';loading.setAttribute('aria-hidden','true');for(let i=0;i<4;i++){const item=document.createElement('div');item.className='ui-skeleton';loading.append(item);}target.before(loading);const pending=new MutationObserver(()=>{if(target.children.length){loading.remove();pending.disconnect();}});pending.observe(target,{childList:true});setTimeout(()=>{loading.remove();pending.disconnect();},15000);});
enhanceFilters();const observer=new MutationObserver(enhanceFilters);observer.observe(document.body,{childList:true,subtree:true});
document.querySelectorAll('table').forEach(table=>{const wrap=document.createElement('div');wrap.className='ui-table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Scrollable table');table.before(wrap);wrap.append(table);});
// Expose announcements for new UI features without intercepting existing messages.
window.MAHA_TOAST=message=>{document.querySelector('.ui-toast')?.remove();const toast=document.createElement('div');toast.className='ui-toast';toast.setAttribute('role','status');toast.textContent=message;document.body.append(toast);setTimeout(()=>toast.remove(),5000);};
})();
